# ─── PYINSTALLER COMPATIBILITY ───────────────────────────────────────────────

def resource_path(relative_path):
    try:
        base_path = sys._MEIPASS
    except Exception:
        base_path = os.path.abspath(".")
    return os.path.join(base_path, relative_path)

# ─── NETWORK HELPERS ──────────────────────────────────────────────────────────

_SSL_CTX = ssl.create_default_context()

def _github_api_json(url: str, timeout: int = 15) -> dict:
    """Fetch JSON from a GitHub API URL with retry logic."""
    for attempt in range(3):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": "Dwnloader/2.0",
                "Accept": "application/vnd.github.v3+json",
            })
            with urllib.request.urlopen(req, timeout=timeout, context=_SSL_CTX) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            if e.code == 403:
                # Rate limited — wait and retry
                retry_after = int(e.headers.get("Retry-After", 60))
                print(f"GitHub rate limited, waiting {retry_after}s...")
                time.sleep(min(retry_after, 60))
            elif e.code in (404, 500, 502, 503):
                wait = 2 ** attempt
                print(f"GitHub API {e.code}, retrying in {wait}s...")
                time.sleep(wait)
            else:
                raise
        except (urllib.error.URLError, OSError) as e:
            wait = 2 ** attempt
            print(f"Network error ({e}), retrying in {wait}s...")
            time.sleep(wait)
    raise RuntimeError(f"Failed to fetch {url} after 3 attempts")

def _download_file(url: str, dest: str, status_cb=None, timeout: int = 300) -> bool:
    """Download a file with retry, redirect following, and progress reporting.

    status_cb(percent: float, downloaded_bytes: int, total_bytes: int | None)
    Returns True on success.
    """
    for attempt in range(3):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": "Dwnloader/2.0",
            })
            with urllib.request.urlopen(req, timeout=timeout, context=_SSL_CTX) as resp:
                total = resp.headers.get("Content-Length")
                total = int(total) if total else None
                downloaded = 0
                chunk_size = 256 * 1024  # 256KB chunks
                with open(dest, "wb") as f:
                    while True:
                        chunk = resp.read(chunk_size)
                        if not chunk:
                            break
                        f.write(chunk)
                        downloaded += len(chunk)
                        if status_cb and total:
                            status_cb(downloaded / total * 100, downloaded, total)
                        elif status_cb:
                            status_cb(-1, downloaded, None)
                return True
        except (urllib.error.URLError, OSError) as e:
            wait = 2 ** attempt
            print(f"Download error ({e}), retrying in {wait}s...")
            time.sleep(wait)
        except urllib.error.HTTPError as e:
            if e.code in (500, 502, 503):
                wait = 2 ** attempt
                print(f"Server error {e.code}, retrying in {wait}s...")
                time.sleep(wait)
            else:
                raise
    return False

