FFMPEG_EXEC = os.path.join(TOOLS_DIR, "ffmpeg.exe"   if IS_WINDOWS else "ffmpeg")

def get_ffmpeg_dir() -> Optional[str]:
    """Return the directory that contains a usable ffmpeg, or None if not found yet."""
    bundled = resource_path("bin/ffmpeg.exe" if IS_WINDOWS else "bin/ffmpeg")
    if os.path.exists(bundled):
        return os.path.dirname(bundled)
    if os.path.exists(FFMPEG_EXEC):
        return TOOLS_DIR
    if shutil.which("ffmpeg"):
        return None   # on PATH; yt-dlp finds it automatically
    return "__missing__"

