class QueueItem:
    """A single download with its own frozen options snapshot.

    Every queued item remembers the settings that were active *when it was
    added*, so one video's options never leak into another item.
    """

    __slots__ = (
        "uid", "url", "title", "quality", "is_music", "fmt", "lang", "folder",
        "status", "phase", "progress", "process", "output_path",
        "frame", "ctrl_host", "title_lbl", "meta_lbl", "bar", "status_lbl",
        "ctls",
    )

    def __init__(self, uid: int, url: str, title: str,
                 quality: str, is_music: bool, fmt: str, lang: str, folder: str):
        self.uid         = uid
        self.url         = url
        self.title       = title or url
        self.quality     = quality
        self.is_music    = is_music
        self.fmt         = fmt
        self.lang        = lang
        self.folder      = folder
        self.status      = "queued"
        self.phase       = "downloading"   # downloading | converting
        self.progress    = 0.0
        self.process     = None
        self.output_path = None
        self.frame       = None
        self.ctrl_host   = None
        self.title_lbl   = None
        self.meta_lbl    = None
        self.bar         = None
        self.status_lbl  = None
        self.ctls        = []

