    # ═══════════════════════════════════════════════════════════════════════
    # ICON
    # ═══════════════════════════════════════════════════════════════════════

    def _apply_icon(self):
        """Set the window icon from ICON_BASE64.

        Strategy (Windows is picky about iconphoto):
        1. Write a real .ico file to a temp path and use iconbitmap() — most
           reliable on Windows and works after PyInstaller packaging.
        2. Fall back to iconphoto() for macOS / Linux.
        """
        if not ICON_BASE64:
            return
        try:
            raw = base64.b64decode(ICON_BASE64)
            img = Image.open(BytesIO(raw)).convert("RGBA")

            if IS_WINDOWS:
                # Save as a proper .ico with multiple sizes so Windows
                # picks the best one for taskbar, title bar, alt-tab, etc.
                ico_path = os.path.join(TOOLS_DIR, "dwnloader_icon.ico")
                os.makedirs(TOOLS_DIR, exist_ok=True)
                img_resized = img.resize((256, 256), Image.Resampling.LANCZOS)
                img_resized.save(ico_path, format="ICO",
                                 sizes=[(16,16),(32,32),(48,48),(64,64),(128,128),(256,256)])
                # iconbitmap must be called AFTER the window is fully realised
                self.after(0, lambda: self.iconbitmap(ico_path))
            else:
                # macOS / Linux: iconphoto works fine
                sizes = [256, 128, 64, 48, 32, 16]
                photos = []
                for s in sizes:
                    photos.append(ImageTk.PhotoImage(img.resize((s, s), Image.Resampling.LANCZOS)))
                self._tk_icons = photos          # keep ALL references alive
                self.iconphoto(True, *photos)

        except Exception as e:
            print(f"Icon error: {e}")

